<script setup lang="ts">import{computed}from'vue';import type{CanvasNode}from'../types';const p=defineProps<{node?:CanvasNode}>();const emit=defineEmits<{change:[CanvasNode]}>();const n=computed(()=>p.node);function set(k:keyof CanvasNode,v:any){if(!p.node)return;emit('change',{...p.node,[k]:Number.isNaN(Number(v))?v:Number(v),updated_at:Date.now()})}</script>
<template><aside v-if="n" class="inspector"><h3>{{n.type.toUpperCase()}}</h3><label>标题<input :value="n.title" @change="set('title',($event.target as HTMLInputElement).value)"></label><div class="pair"><label>X<input type="number" :value="Math.round(n.x)" @change="set('x',($event.target as HTMLInputElement).value)"></label><label>Y<input type="number" :value="Math.round(n.y)" @change="set('y',($event.target as HTMLInputElement).value)"></label></div><div class="pair"><label>宽<input type="number" :value="Math.round(n.width)" @change="set('width',($event.target as HTMLInputElement).value)"></label><label>高<input type="number" :value="Math.round(n.height)" @change="set('height',($event.target as HTMLInputElement).value)"></label></div><label>旋转<input type="range" min="-180" max="180" :value="n.rotation" @input="set('rotation',($event.target as HTMLInputElement).value)"><span>{{n.rotation}}°</span></label><small>ID {{n.id.slice(0,8)}}</small></aside></template>
